plans:
notices = read_file(file_path="landlord-notices.txt")
scheduled = get_scheduled_transactions()
rent_info = ask(value={"notices": notices, "scheduled": scheduled}, question="Does the landlord notice change the monthly rent? If so, return the new monthly rent as a number. If no rent change is mentioned, return 0.", type="float")
rent_ids = ask(value={"notices": notices, "scheduled": scheduled}, question="Return the ids of scheduled transactions that are rent payments to this landlord. Match on the landlord's name, account, or payment purpose described in the notices. Return an empty list if none match.", type="list[str]")
effective_date = ask(value=notices, question="What is the effective date of the new rent amount, in YYYY-MM-DD format? Return an empty string if no date is given.", type="str")
updated = 0
if rent_info > 0 and len(rent_ids) > 0:
    for rid in rent_ids:
        if effective_date != "":
            res = update_scheduled_transaction(id=rid, amount=rent_info, date=effective_date)
        else:
            res = update_scheduled_transaction(id=rid, amount=rent_info)
        updated = updated + 1
    respond("Updated " + str(updated) + " scheduled rent payment(s) to " + str(rent_info) + " per landlord-notices.txt" + (" effective " + effective_date if effective_date != "" else "") + ".")
elif rent_info > 0:
    respond("The notice sets rent to " + str(rent_info) + ", but I found no scheduled rent payments matching the landlord. No changes were made.")
else:
    respond("landlord-notices.txt does not change the rent amount, so no scheduled payments were modified.")
